import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, address actor) public {
        // Restrict actor to non-zero address with sufficient balance to avoid overflow of internal computation.
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount <= type(uint256).max / 2);

        // Fund the actor and make a deposit.
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // The invariant: after a single deposit, the contract's ETH balance must be at least the recorded balance of the depositor.
        // The reference C enforces this by preventing overflow; the buggy M accepts overflow and can produce a recorded balance
        // that exceeds the actual ETH received by the contract.
        uint256 recordedBalance = c.balances(actor);
        assertTrue(address(c).balance >= recordedBalance);
    }
}

