pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, uint8 dummy) public {
        // Keep amounts within reasonable range to avoid overflow in comparisons
        uint256 adjustedDeposit = bound(depositAmount, 1, 1_000_000 ether);
        uint256 adjustedWithdraw = bound(withdrawAmount, 1, 1_000_000 ether);

        // Make two distinct callers with sufficient funds
        address caller1 = address(0x1234);
        address caller2 = address(0x5678);
        vm.assume(caller1 != caller2);

        vm.deal(caller1, adjustedDeposit + 1 ether);
        vm.deal(caller2, adjustedDeposit + 1 ether);

        // Caller1 deposits
        vm.prank(caller1);
        c.deposit{value: adjustedDeposit}();

        // Caller2 deposits
        vm.prank(caller2);
        c.deposit{value: adjustedDeposit}();

        // Ensure withdrawAmount does not exceed Caller1's balance
        uint256 bal1 = c.balances(caller1);
        vm.assume(adjustedWithdraw <= bal1);

        // Caller1 withdraws using the potentially buggy function
        vm.prank(caller1);
        uint256 etherBefore = address(c).balance;
        c.withdraw(adjustedWithdraw);
        uint256 etherAfter = address(c).balance;

        // After the withdraw, the contract's Ether balance must be at least the sum of recorded balances.
        // The buggy version fails to decrement caller1's internal balance, causing the total recorded
        // balance to exceed the contract's actual Ether holding in subsequent calls.
        uint256 totalRecorded = c.balances(caller1) + c.balances(caller2);
        assertTrue(address(c).balance >= totalRecorded, "Invariant violated: contract Ether under-collateralized");
    }
}

